const bankNav=document.createElement('button');bankNav.dataset.nav='bank';bankNav.dataset.icon='network';bankNav.textContent='Bank connectivity';document.querySelector('aside .nav').append(bankNav);
document.querySelector('.org').innerHTML='<span class="avatar">FS</span><div>Foxsquare<div class="small">Payments operations</div></div>';
document.querySelector('.secure').innerHTML='<strong>Workspace controls</strong><div class="small">Masked payment details.<br>Manage access and connectivity.</div>';
document.querySelector('.gateway-title').textContent='Foxsquare / Payout';
document.querySelector('.topright').append(document.querySelector('.bot-toggle'));
document.querySelector('.topright .avatar').remove();
document.querySelector('.topright').insertAdjacentHTML('afterbegin','<button class="btn secondary" onclick="openAccount(\'signin\')">Sign in</button><button class="btn" onclick="openAccount(\'signup\')">Sign up</button>');
const accountModal=document.createElement('div');accountModal.className='modal';accountModal.id='accountModal';accountModal.innerHTML='<div class="dialog" role="dialog" aria-modal="true" aria-labelledby="accountTitle" id="accountDialog"></div>';document.body.append(accountModal);
let accountTrigger;
function closeAccount(){accountModal.classList.remove('open');accountTrigger?.focus()}
function openAccount(mode){accountTrigger=document.activeElement;const signup=mode==='signup';document.getElementById('accountDialog').innerHTML=`<button class="close" aria-label="Close account form" onclick="closeAccount()">×</button><h2 id="accountTitle">${signup?'Create your account':'Sign in to Foxsquare'}</h2><p style="margin-top:10px">${signup?'Manage your business payments in one workspace.':'Access your payments workspace.'}</p><form id="accountForm">${signup?'<label for="accountName">Full name</label><input id="accountName" autocomplete="name" required maxlength="80"><label for="accountCompany">Business name</label><input id="accountCompany" autocomplete="organization" required maxlength="120">':''}<label for="accountEmail">Work email</label><input id="accountEmail" type="email" autocomplete="email" required><label for="accountPassword">Password</label><input id="accountPassword" type="password" autocomplete="${signup?'new-password':'current-password'}" minlength="8" required>${signup?'<label for="accountConfirm">Confirm password</label><input id="accountConfirm" type="password" autocomplete="new-password" minlength="8" required>':''}<button class="btn" type="submit">${signup?'Create account':'Sign in'}</button><p id="accountFeedback" role="status" class="answer"></p><p class="small" style="margin-top:14px">Account service is not connected. Credentials are not sent or stored.</p></form><button class="account-switch" onclick="openAccount('${signup?'signin':'signup'}')">${signup?'Already have an account? Sign in':'New to Foxsquare? Sign up'}</button>`;accountModal.classList.add('open');document.getElementById(signup?'accountName':'accountEmail').focus();document.getElementById('accountForm').onsubmit=e=>{e.preventDefault();if(signup&&document.getElementById('accountPassword').value!==document.getElementById('accountConfirm').value){document.getElementById('accountFeedback').textContent='Passwords do not match.';return}document.getElementById('accountFeedback').textContent='Account access is not available yet. Please contact Foxsquare to arrange onboarding.';document.getElementById('accountPassword').value='';if(signup)document.getElementById('accountConfirm').value=''}}
accountModal.onclick=e=>{if(e.target===accountModal)closeAccount()};
document.addEventListener('keydown',e=>{if(!accountModal.classList.contains('open'))return;if(e.key==='Escape')closeAccount();if(e.key==='Tab'){const items=[...accountModal.querySelectorAll('button,input')];const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
const mobileNav=document.createElement('nav');mobileNav.className='mobile-nav';mobileNav.setAttribute('aria-label','Workspace navigation');mobileNav.innerHTML=['overview','transactions','settlements','analytics','integrations','bank','settings'].map(n=>`<button data-nav="${n}">${({overview:'Overview',transactions:'Transactions',settlements:'Settlements',analytics:'Analytics',integrations:'API scope',bank:'Bank connectivity',settings:'Security'})[n]}</button>`).join('');document.querySelector('.topbar').after(mobileNav);
document.querySelector('.ask h2').textContent='Ask Your Data';
const originalNav=showNav;
const integrationScopes={
 collections:{title:'Collections & payment status',desc:'Proposed interface for initiating a collection request and resolving its final status.',items:['Bank-issued reference and Foxsquare correlation ID','Idempotent request handling and duplicate protection','Status enquiry for timeouts and delayed callbacks'],request:{operation:'collection.status',correlation_id:'FSQ-10482',bank_reference:'BANK-REFERENCE-PENDING',currency:'INR'},event:'collection.status.updated'},
 settlements:{title:'Settlement visibility',desc:'Proposed interface for settlement schedules, bank references, and settlement outcomes.',items:['Settlement reference linked to underlying transactions','Expected and confirmed settlement timestamps','Exception handling for pending or rejected settlement batches'],request:{operation:'settlement.enquiry',settlement_id:'STL-00284',merchant_id:'FSQ-MERCHANT-001',currency:'INR'},event:'settlement.status.updated'},
 reconciliation:{title:'Reconciliation & exceptions',desc:'Proposed bank statement or settlement-report exchange for matching ledger records.',items:['Reference, amount, and currency matching','Unmatched-item queue with reason and ownership','Report totals and reconciliation checkpoint history'],request:{operation:'reconciliation.report',period:'2026-10-14',format:'JSON',merchant_id:'FSQ-MERCHANT-001'},event:'reconciliation.report.available'},
 webhooks:{title:'Event notifications',desc:'Proposed bank-to-Foxsquare event delivery for asynchronous payment updates.',items:['Authenticated callbacks and agreed payload signing','Timestamp validation and replay controls','Retry policy, acknowledgement, and duplicate event handling'],request:{event:'payment.status.updated',event_id:'EVT-10482',correlation_id:'FSQ-10482',status:'SUCCESS'},event:'payment.status.updated'}
};
let currentScope='collections';
function apiView(){return `<div class="section-heading"><div><h2>Proposed API scope</h2><p>Field names and operations below are an interface proposal, subject to bank specifications.</p></div><span class="neutral-status">Specification pending</span></div><div class="tabs" aria-label="API categories">${Object.keys(integrationScopes).map(k=>`<button onclick="selectScope('${k}')" data-scope="${k}" class="${k===currentScope?'active':''}">${({collections:'Collections',settlements:'Settlements',reconciliation:'Reconciliation',webhooks:'Webhooks'})[k]}</button>`).join('')}</div><div id="apiDetail"></div><div class="section-heading"><div><h2>Event processing walkthrough</h2><p>Local event trace · No request is sent to a bank endpoint.</p></div><button class="btn secondary" onclick="runEvent()" data-icon="play">Run event trace</button></div><ul class="event-list" id="eventTrace"><li><span>Awaiting event trace</span><code>Not connected</code></li></ul>`}
function selectScope(scope){currentScope=scope;const data=integrationScopes[scope];document.querySelectorAll('[data-scope]').forEach(b=>b.classList.toggle('active',b.dataset.scope===scope));document.getElementById('apiDetail').innerHTML=`<div class="bank-layout api-detail"><div><h2>${data.title}</h2><p>${data.desc}</p><ul>${data.items.map(i=>`<li>${i}</li>`).join('')}</ul><span class="neutral-status">Bank validation required</span></div><div class="codebox"><div class="code-label"><span>PROPOSED PAYLOAD · JSON</span><button title="Copy proposed payload" onclick="copyPayload()" data-icon="copy">Copy</button></div><code id="payload"></code></div></div>`;document.getElementById('payload').textContent=JSON.stringify(data.request,null,2);icons()}
async function copyPayload(){try{await navigator.clipboard.writeText(JSON.stringify(integrationScopes[currentScope].request,null,2));toast('Proposed payload copied.')}catch{toast('Clipboard unavailable in this browser.')}}
function runEvent(){const event=integrationScopes[currentScope].event;document.getElementById('eventTrace').innerHTML=`<li><span>01 · ${event}</span><code>Local input</code></li><li><span>02 · Correlation reference checked</span><code>FSQ-10482</code></li><li><span>03 · Duplicate event check</span><code>Unique event</code></li><li><span>04 · Ledger status updated in walkthrough</span><code>Complete</code></li>`;toast('Local event trace completed.')}
function bankView(){return `<div class="bank-summary"><div><div class="small">INTEGRATION STATUS</div><div class="summary-value">Scope review</div><div class="small">API configuration</div></div><div><div class="small">CONNECTIVITY</div><div class="summary-value">Not connected</div><div class="small">Credentials not provisioned</div></div><div><div class="small">ENVIRONMENT</div><div class="summary-value">Local workspace</div><div class="small">No production traffic</div></div><div><div class="small">NEXT MILESTONE</div><div class="summary-value">Sandbox access</div><div class="small">Subject to bank approval</div></div></div><div class="section-heading"><div><h2>Proposed transaction lifecycle</h2><p>A shared reference across the payment, bank response, and merchant ledger.</p></div></div><div class="flow"><div class="flow-step"><div class="step-number">01 / INITIATE</div><strong>Merchant request</strong><p>Foxsquare creates a request with a unique correlation reference.</p></div><div class="flow-step"><div class="step-number">02 / PROCESS</div><strong>Bank API</strong><p>The bank validates and processes the agreed operation.</p></div><div class="flow-step"><div class="step-number">03 / CONFIRM</div><strong>Status & callback</strong><p>Signed event or status enquiry confirms the payment outcome.</p></div><div class="flow-step"><div class="step-number">04 / RECONCILE</div><strong>Merchant ledger</strong><p>Settlement references are matched and exceptions reviewed.</p></div></div><div class="bank-layout"><div><div class="section-heading"><h2>Service configuration</h2></div><p style="font-size:13px">Select the services for your bank connection.</p><div class="scope-list"><label><input type="checkbox" name="scope" value="Collections & status enquiry" checked> Collections & status enquiry</label><label><input type="checkbox" name="scope" value="Settlement reports" checked> Settlement reports</label><label><input type="checkbox" name="scope" value="Reconciliation feeds" checked> Reconciliation feeds</label><label><input type="checkbox" name="scope" value="Event notifications" checked> Event notifications</label><label><input type="checkbox" name="scope" value="Payouts, subject to approval"> Payouts, subject to approval</label></div><div class="scope-actions"><button class="btn" onclick="buildPlan()" data-icon="list-checks">Prepare scope</button><button class="btn secondary" onclick="downloadScope()" data-icon="download">Export configuration</button></div><div id="scopeOutput" class="plan-output"><strong>Connection requirements</strong>API specifications, credentials, and acceptance criteria are required to activate the connection.</div></div><div><div class="section-heading"><h2>Connection setup stages</h2></div><table class="requirements"><thead><tr><th>Stage</th><th>Acceptance criteria</th><th>Status</th></tr></thead><tbody><tr><td>1. Discovery</td><td>API documents, service scope, ownership, and commercial terms</td><td>Review</td></tr><tr><td>2. Sandbox</td><td>Credentials, connectivity, payloads, and callback tests</td><td>Pending</td></tr><tr><td>3. Validation</td><td>Reconciliation, failure handling, and security review</td><td>Planned</td></tr><tr><td>4. Production</td><td>Bank sign-off, controlled rollout, and monitoring</td><td>Planned</td></tr></tbody></table></div></div><div class="section-heading"><h2>Connection requirements</h2></div><table class="requirements"><thead><tr><th>Area</th><th>Configuration details</th></tr></thead><tbody><tr><td>API & onboarding</td><td>Supported operations, eligibility, required documentation, and sandbox provisioning</td></tr><tr><td>Authentication</td><td>Credential model, certificates, IP allowlisting, and key rotation requirements</td></tr><tr><td>Operations</td><td>Cut-off times, rate limits, retry policies, settlement cycles, and escalation contacts</td></tr><tr><td>Acceptance</td><td>Required test cases, reconciliation format, security evidence, and go-live approval</td></tr></tbody></table>`}
function selectedServices(){return [...document.querySelectorAll('input[name="scope"]:checked')].map(i=>i.value)}
function buildPlan(){const services=selectedServices();document.getElementById('scopeOutput').replaceChildren();const title=document.createElement('strong');title.textContent='Selected services';document.getElementById('scopeOutput').append(title,document.createTextNode(services.length?services.join(' · '):'Select at least one service to prepare the scope.'))}
function downloadScope(){const services=selectedServices();const text='FOXSQUARE | BANK API INTEGRATION PROPOSAL\n\nSelected services\n'+services.map(s=>'- '+s).join('\n')+'\n\nCurrent status: scope review. Bank connectivity and production access are pending.\n\nBank inputs requested\n- API specifications and onboarding requirements\n- Sandbox credentials and authentication requirements\n- Settlement cycles and reconciliation formats\n- Rate limits, callback retries, and escalation contacts\n- Acceptance tests and go-live approval\n\nMilestones\n1. Discovery and scope agreement\n2. Sandbox connectivity and API tests\n3. Reconciliation and security validation\n4. Bank sign-off and controlled production rollout\n';const blob=new Blob([text],{type:'text/plain'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Foxsquare-Bank-Integration-Brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function securityView(){const controls=[['shield-check','Sensitive data masking','Customer and card identifiers are masked in the interface.','Interface applied'],['key-round','Authentication & authorization','Bank credentials, merchant roles, and least-privilege access must be validated with the backend.','Required'],['lock-keyhole','Transport & credential protection','Agree TLS, secret storage, certificate requirements, and rotation with the bank.','Required'],['scan-line','AI data access boundary','Restrict analytics to authorized, masked fields with a server-enforced allowlist.','Required'],['history','Audit & operational controls','Record sensitive actions and review webhook replay, retries, and reconciliation exceptions.','Required']];return `<div class="section-heading"><div><h2>Security review register</h2><p>Controls to validate before bank connectivity and production approval.</p></div><span class="neutral-status">Production review pending</span></div>${controls.map(c=>`<div class="security-row"><div><strong class="control-icon"><i data-icon="${c[0]}"></i>${c[1]}</strong><p>${c[2]}</p></div><span class="neutral-status">${c[3]}</span></div>`).join('')}<div class="section-heading"><h2>Acceptance evidence</h2></div><table class="requirements"><tr><th>Review area</th><th>Evidence to agree</th><th>Status</th></tr><tr><td>Access controls</td><td>Role matrix, credential lifecycle, and negative authorization tests</td><td>Pending</td></tr><tr><td>Data protection</td><td>Data-flow review, masking tests, and storage configuration</td><td>Pending</td></tr><tr><td>API resilience</td><td>Timeouts, retries, duplicate handling, and reconciliation results</td><td>Pending</td></tr></table>`}
function settlementView(){return `<div class="section-heading"><div><h2>Settlement & reconciliation</h2><p>Bank references and merchant ledger entries reviewed together.</p></div><button class="btn secondary" onclick="reconcile()" data-icon="git-compare-arrows">Run reconciliation</button></div><div class="reconcile-results" id="reconcileResults"><div><strong>2</strong><span class="small">Ledger batches</span></div><div><strong>—</strong><span class="small">Matched references</span></div><div><strong>—</strong><span class="small">Review items</span></div></div><div class="tablewrap"><table><tr><th>Settlement</th><th>Amount</th><th>Destination</th><th>Expected date</th><th>Ledger status</th><th>Reconciliation</th></tr><tr><td>STL-00284</td><td>₹2,46,800</td><td>Bank ••6821</td><td>15 Oct 2026</td><td><span class="status pending">Scheduled</span></td><td id="rec1">Not reviewed</td></tr><tr><td>STL-00283</td><td>₹1,84,200</td><td>Bank ••6821</td><td>14 Oct 2026</td><td><span class="status">Recorded</span></td><td id="rec2">Not reviewed</td></tr></table></div><p class="safety-caption">Local reconciliation walkthrough. Bank statement feeds and transfers are not connected.</p>`}
function reconcile(){document.getElementById('rec1').innerHTML='<span class="status pending">Awaiting bank reference</span>';document.getElementById('rec2').innerHTML='<span class="status">Reference matched</span>';document.getElementById('reconcileResults').innerHTML='<div><strong>2</strong><span class="small">Ledger batches</span></div><div><strong>1</strong><span class="small">Matched references</span></div><div><strong>1</strong><span class="small">Review items</span></div>';toast('Local reconciliation completed. One item needs review.')}
showNav=function(n){if(n!=='bank')originalNav(n);else{document.getElementById('dashboard').style.display='none';document.getElementById('transactionsPanel').style.display='none';document.getElementById('extraPanel').style.display='block'}document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===n));const headings={overview:['Payments command center','Collections, settlements, and merchant operations in one clear view.'],bank:['Bank connectivity','Manage banking services, connectivity, and onboarding requirements.'],integrations:['API integration workspace','Explore the proposed services, payloads, and event flow.'],settings:['Security & control','Define the controls and evidence for bank integration approval.'],settlements:['Settlement operations','Trace settlement references and review reconciliation outcomes.']};if(headings[n]){document.getElementById('pageTitle').textContent=headings[n][0];document.getElementById('pageSubtitle').textContent=headings[n][1]}document.querySelector('.actions').style.display=['overview','analytics','transactions'].includes(n)?'flex':'none';const extra=document.getElementById('extraPanel');if(n==='bank')extra.innerHTML=bankView();if(n==='integrations'){extra.innerHTML=apiView();selectScope(currentScope)}if(n==='settings')extra.innerHTML=securityView();if(n==='settlements')extra.innerHTML=settlementView();icons();};
document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>showNav(b.dataset.nav));
showNav('overview');
